{"statusCode":401,"error":"Unauthorized","message":"missing 'apikey' query parameter"}

// eth_getCode on chain 56 -> all four EntryPoints hold bytecode
// 0x5FF137D4... = 23689 bytes  (v0.6)
// 0x00000000717... = 16035 bytes (v0.7)
// 0x4337084D... = 21738 bytes  (v0.8)
// 0x433709009B... = 22425 bytes (fourth EP, likely v0.8.x patch)

// The 'bundler' is NOT a privileged role. Any EOA can call handleOps.
// AiKi's backend relayer becomes its own bundler:

interface IEntryPoint {
    function handleOps(PackedUserOperation[] calldata ops,
                       address payable beneficiary) external;
    // simulate first, off-chain, via eth_call:
    function simulateHandleOp(PackedUserOperation calldata op,
                              address target, bytes calldata targetCallData) external;
    function depositTo(address account) external payable;
    function addStake(uint32 unstakeDelaySec) external payable;  // paymasters must stake
}

// AiKi self-relay loop:
//  1. agent signs userOp with session key (SmartSession PermissionId in signature)
//  2. backend calls simulateHandleOp via eth_call to get gas limits
//  3. backend EOA sends handleOps([userOp], aikiTreasury) as a normal tx
//  4. EntryPoint refunds backend from account deposit OR AiKi's own paymaster deposit
//
// For sponsorship without a vendor: deploy AiKiPaymaster, addStake() + depositTo(),
// sign paymasterAndData off-chain in the backend. Zero third-party dependency.
//
// CONSTRAINT (verified from ISmartSession.sol): SmartSession only exposes
//   validateUserOp(...) -- an ERC-7579 validator hook.
// There is no direct execute-with-session-key entry point, so you CANNOT bypass
// EntryPoint and have the relayer call the 7702-delegated EOA directly while
// still getting SmartSession policy enforcement.
